using checkpoint::SerializableTraits< T, S >::nonintrustive_serialize_t = decltype(serialize(
   std::declval<V&>(),
   std::declval<U&>()
 ))

using checkpoint::SerializableTraits< T, S >::nonintrustive_reconstruct_t = decltype(
   reconstruct(
     std::declval<U*&>(),
     std::declval<void*>()
   )
 )

using checkpoint::SerializableTraits< T, S >::specialized_reconstruct_t = decltype(
   checkpoint::CheckpointReconstructor<U>::reconstruct(
     std::declval<U*&>(),
     std::declval<void*>()
   )
 )
